import sys

def count_ones(n, l, r):
    def transform(x):
        if x == 0 or x == 1:
            return [x]
        else:
            half = x // 2
            mod = x % 2
            return [half, mod, half]

    def count_ones_in_range(lst, start, end):
        return sum(1 for i in range(start, end) if lst[i] == 1)

    current_list = [n]
    while any(x > 1 for x in current_list):
        new_list = []
        for x in current_list:
            new_list.extend(transform(x))
        current_list = new_list

    return count_ones_in_range(current_list, l - 1, r)

def main():
    import sys
    input = sys.stdin.read().strip()
    n, l, r = map(int, input.split())
    result = count_ones(n, l, r)
    print(result)

if __name__ == "__main__":
    main()
